  "a_sentences": [
    {
      "a_text": "La recourante fait valoir une violation de l'interdiction du déni de justice et demande une modification de la législation cantonale.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "La juridiction fédérale examine d'office sa compétence et les autres conditions de recevabilité.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Une décision peut être attaquée devant le Tribunal fédéral si elle porte sur un acte cantonal ou communal de nature normative.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Le canton de Saint-Gall ne prévoit pas de recours direct contre ses actes normatifs.",
      "b_propositions": ["P4", "P5"]
    },
    {
      "a_text": "Le Tribunal fédéral ne peut entrer en matière que si un droit à l'action législative découle d'une norme fédérale ou conventionnelle claire et précise.",
      "b_propositions": ["P3", "P7"]
    },
    {
      "a_text": "Le Tribunal fédéral ne discerne pas en quoi le gouvernement cantonal aurait agi par voie normative.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Faute d'une obligation législative suffisamment déterminée, le Tribunal fédéral n'est pas compétent pour examiner la cause.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral n'entre pas en matière sur la demande de constatation d'un déni de justice, faute d'intérêt digne de protection démontré.",
      "b_propositions": ["P8"]
    }
  ]
}
